with matched_keys as (select id, segment from customers intersect all select id, segment from customers where credit_limit < 10700), kept_rows as (select s.* from customers s join matched_keys k on s.id = k.id and s.segment = k.segment) select date_trunc('year', signup_date) as year_start, segment, sum(case when city = 'London' then credit_limit else 0 end) as london_credit_limit, sum(case when country = 'SG' then credit_limit else 0 end) as sg_credit_limit, count(distinct segment) as distinct_segments, round(avg(age), 2) as avg_age, sort_array(collect_set(country)) as country_list, sort_array(collect_set(city)) as city_list, percent_rank() over (partition by date_trunc('year', signup_date) order by sum(case when city = 'London' then credit_limit else 0 end) desc) as london_credit_limit_percent_rank from kept_rows group by date_trunc('year', signup_date), segment
